import{c as n,Q as t,j as a,g as l}from"./chunks/framework.hhGiamYR.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-09-27T00:00:00.000Z","source":"machiavelli/discourses/book2/04-第四章"},"headers":[],"relativePath":"fragments/2026-09-27.md","filePath":"fragments/2026-09-27.md"}'),r={name:"fragments/2026-09-27.md"};function s(o,e,u,p,c,d){return t(),a("div",null,[...e[0]||(e[0]=[l("p",null,'托斯卡纳人用平等结盟的方式扩张，十二座城市——丘西、维爱、阿雷佐、菲耶索莱、沃尔泰拉——谁也不高过谁。我数着这几个地名，心里发冷。他们曾经海陆都强，曾经用"亚德里亚人"给一片海命了名，到今天那海还叫这个名字。可他们自己呢，被法兰克人夺走伦巴第，被罗马人灭掉，两千年前的丰功伟业，如今几乎没人记得。',-1),l("p",null,'一个平等到谁也不发号施令的联盟，最后的报应不是失败，是被遗忘。因为没人记得住一个没有名字的集体。我写《论李维》的这会儿，佛罗伦萨正是一个"生活在平等中"的共和国——我也会像托斯卡纳人一样，被记住一片海的名字，然后自己被抹掉吗。',-1),l("hr",null,null,-1),l("p",null,'罗马的方式我反复看。它结盟，却始终留着"帝国的枢纽之地和发号施令的头衔"。盟友在不知不觉间，不辞辛劳与鲜血，心甘情愿地臣服。等他们发现自己上了圈套，想补救，已经太晚了。',-1),l("p",null,'我盯着"心甘情愿"四个字，觉得这才是最可怕的地方。不是武力征服了他们，是他们自己走进来的。等到他们密谋造反，就成了战败者，处境反而更糟——从盟友变成臣属。我干外交那些年，见过太多这样的圈套。区别只在于，罗马的圈套摆了两百年，而我见过的那些，往往三年就散了。差在哪里？差在头衔。罗马从来不肯让出那个发号施令的名分，一天都不让。而我们，总是太急着显得谦和。',-1),l("hr",null,null,-1),l("p",null,'第三种方式——不结盟，直接征服，斯巴达和雅典的路——我写它"完全无效"。理由只有一个：它们拿到了自己守不住的领土。以暴力统治习惯于自由生活的城市，是件劳神费力的事。没有兵，没有人口，发号施令就无从谈起。那两个城邦一样都没有，所以亡了。',-1),l("p",null,"写到这里我停下来，想起我自己的民军。我那年费尽力气武装佛罗伦萨，最后普拉托一役，它像纸一样被撕碎。我是不是也干过同样的事——想要一种超过自己能守的东西？我现在责备斯巴达和雅典，可那支民军溃散的那个下午，我也一样。区别只是，我有时间把责备写下来，它们没有。",-1),l("hr",null,null,-1),l("p",null,"瑞士人、士瓦本同盟，还有古代的亚该亚人和埃托利亚人，走的都是托斯卡纳的旧路。这种结盟到十二或十四个共同体就止步不前了，然后转向两件事：收保护国的钱，替别的君主卖命。李维记过，马其顿国王菲利普跟弗拉米尼乌斯谈判，一个埃托利亚的执政官在旁边争执，被痛斥贪婪无信——同一场战争，两边都有埃托利亚人的旗徽。",-1),l("p",null,"我读到这儿笑了一下。不是笑他们。是我看懂了那种活法：本事不小，却谁都不属于，最后只能把自己租出去。这跟我在美第奇复辟后四处求差事的样子，有什么两样。托斯卡纳人守住了平等，代价是谁也不欠他们一个名字。我不想要那个下场。可我又能要什么呢。",-1)])])}const f=n(r,[["render",s]]);export{m as __pageData,f as default};
